/// Per-worker scratch.  Owned by the caller and passed in, so the token path performs NO allocations
/// (P2.T10) - the kernel itself allocates nothing.
struct ExpertScratch {
    ActQ a1;
    ActQ a2;
    alignas(64) float ff[FF];
